// NEET UG Biology: Chemical coordination and integration (NCERT Class 11, Chapter 22, rationalised). All questions original fibub work.
import { pick, int, choose, fmt, shuffleOpts, numOpts, g } from '../_entrance.js';

const E = ['neet'];
const items = [];
const groups = {};
let n = 0, pos = 0;
const POS = [2, 0, 3, 1];
const PFX = 'cco';
const nid = () => `${PFX}-${String(++n).padStart(3, '0')}`;
const AR = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const ST = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'];
function mc(level, sub, q, correct, wrongs, sol, trap, format = 'single') {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format, exams: E, sub, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function asr(level, sub, A, R, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'assertion', exams: E, sub, q: `<b>Assertion (A):</b> ${A}<br><b>Reason (R):</b> ${R}`, options: AR, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function stm(level, sub, s1, s2, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: E, sub, q: `<b>Statement I:</b> ${s1}<br><b>Statement II:</b> ${s2}`, options: ST, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function match(level, sub, key, title, list1, list2, correct, wrongs, sol, trap) {
  groups[key] = { title, list1, list2 };
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: E, sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function pass(key, title, passage) { groups[key] = { title, passage }; }
function pq(key, level, sub, q, correct, wrongs, sol, trap) {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'passage', exams: E, sub, group: key, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function cnt(level, sub, q, correct, wrongs, sol, trap) { mc(level, sub, q, correct, wrongs, sol, trap, 'statements'); }

// ---------------------------------------------------------------- Level 1
mc(1, 'hormones', 'Hormones are best described as', 'non-nutrient chemicals that act as intercellular messengers and are made in trace amounts', ['enzymes made in large quantities', 'food molecules stored in glands', 'electrical signals carried by nerves'], 'Hormones are produced in very small amounts by endocrine cells and carried to target cells. They are not food or enzymes.');
mc(1, 'hormones', 'Endocrine glands are called ductless glands because they', 'release their secretions directly into the blood or tissue fluid', ['have no cells', 'release secretions through long ducts', 'have no blood supply'], 'Hormones pass into the blood without a duct. Exocrine glands such as salivary glands use ducts.');
mc(1, 'hypothalamus', 'The part of the brain that is the master link between the nervous and endocrine systems is the', 'hypothalamus', ['cerebellum', 'medulla oblongata', 'corpus callosum'], 'The hypothalamus has neurosecretory cells that make hormones controlling the pituitary.');
mc(1, 'pituitary', 'The pituitary gland lies in a bony cavity called the', 'sella tursica', ['orbit', 'sinus', 'foramen magnum'], 'The pituitary sits in the sella tursica and is attached to the hypothalamus by a stalk.');
mc(1, 'pituitary', 'Growth hormone is secreted by the', 'anterior pituitary (pars distalis)', ['posterior pituitary', 'thyroid', 'adrenal medulla'], 'GH is made by the pars distalis of the adenohypophysis.');
mc(1, 'pituitary', 'Oxytocin acts on the', 'smooth muscles of the uterus and mammary glands', ['pancreas', 'adrenal cortex', 'thyroid'], 'Oxytocin causes strong uterine contractions during childbirth and milk ejection from the mammary gland.');
mc(1, 'pituitary', 'Which hormone helps the kidney to conserve water?', 'Vasopressin (ADH)', ['Oxytocin', 'Glucagon', 'Calcitonin'], 'ADH makes the distal tubules reabsorb more water and so reduces water loss in urine.');
mc(1, 'pineal', 'The pineal gland secretes', 'melatonin', ['thyroxine', 'insulin', 'cortisol'], 'Melatonin controls the 24-hour (diurnal) rhythm, such as the sleep-wake cycle.');
mc(1, 'thyroid', 'The mineral needed for the synthesis of thyroid hormones is', 'iodine', ['iron', 'calcium', 'sodium'], 'Thyroxine (T<sub>4</sub>) and triiodothyronine (T<sub>3</sub>) contain iodine.');
mc(1, 'thyroid', 'Deficiency of iodine in the diet leads to', 'simple goitre', ['diabetes mellitus', 'acromegaly', 'Addison’s disease'], 'Low iodine causes hypothyroidism and the thyroid enlarges, which is called simple goitre.');
mc(1, 'parathyroid', 'Parathyroid hormone (PTH) acts to', 'increase the blood calcium level', ['decrease the blood calcium level', 'increase blood glucose', 'decrease blood pressure'], 'PTH is a hypercalcaemic hormone. It acts on bones, kidney tubules and the intestine.');
mc(1, 'thymus', 'The thymus secretes', 'thymosins', ['thyroxine', 'gastrin', 'secretin'], 'Thymosins help in the differentiation of T-lymphocytes.');
mc(1, 'adrenal', 'The adrenal glands are located', 'on the anterior (upper) side of each kidney', ['inside the brain', 'below the stomach', 'near the heart'], 'Each kidney has an adrenal gland on top. It has an outer cortex and an inner medulla.');
mc(1, 'adrenal', 'The hormones called "fight or flight" hormones are', 'adrenaline and noradrenaline', ['insulin and glucagon', 'oestrogen and progesterone', 'thyroxine and calcitonin'], 'The adrenal medulla secretes these catecholamines in stress.');
mc(1, 'pancreas', 'Insulin is secreted by the', 'β-cells of the islets of Langerhans', ['α-cells of the islets', 'liver cells', 'adrenal cortex'], 'α-cells make glucagon, β-cells make insulin.');
mc(1, 'pancreas', 'The hormone that lowers blood glucose is', 'insulin', ['glucagon', 'adrenaline', 'cortisol'], 'Insulin is hypoglycaemic. Glucagon is hyperglycaemic.');
mc(1, 'gonads', 'Testosterone is secreted by the', 'Leydig (interstitial) cells of the testis', ['Sertoli cells only', 'ovary', 'adrenal medulla'], 'Leydig cells between the seminiferous tubules secrete androgens.');
mc(1, 'gonads', 'Which hormone maintains pregnancy?', 'Progesterone', ['Glucagon', 'Thyroxine', 'Vasopressin'], 'Progesterone, from the corpus luteum, supports pregnancy and prepares the mammary glands.');
mc(1, 'disorders', 'Diabetes mellitus is caused by', 'a lack of insulin or its action', ['a lack of ADH', 'excess thyroxine', 'a lack of iodine'], 'Insulin deficiency causes prolonged high blood glucose. Lack of ADH causes diabetes insipidus.');
mc(1, 'heart, kidney, GI tract', 'Erythropoietin is secreted by the', 'kidney', ['heart', 'stomach', 'pancreas'], 'The juxtaglomerular cells of the kidney secrete erythropoietin, which stimulates the formation of red blood cells.');
mc(1, 'heart, kidney, GI tract', 'Gastrin is secreted by the', 'stomach (gastric mucosa)', ['pancreas', 'liver', 'kidney'], 'Gastrin acts on gastric glands for secretion of HCl and pepsinogen.');

// ---------------------------------------------------------------- Level 2
mc(2, 'hormones', 'Which is a correct difference between neural and chemical coordination?', 'Chemical coordination is slower but its effects last longer', ['Chemical coordination is faster and shorter', 'Neural coordination uses blood to carry its signal', 'Only chemical coordination is point-to-point'], 'Nerve impulses are quick and point-to-point. Hormones travel in the blood and act on target cells over a longer time.');
mc(2, 'hormones', 'Which of these is chemically a steroid hormone?', 'Cortisol', ['Insulin', 'Glucagon', 'Oxytocin'], 'Cortisol, aldosterone, testosterone, oestrogen and progesterone are steroids. Insulin, glucagon and oxytocin are peptides.');
mc(2, 'hormones', 'Which of these is an iodothyronine?', 'Thyroxine', ['Cortisol', 'Adrenaline', 'Insulin'], 'Thyroid hormones are iodinated derivatives of the amino acid tyrosine and are called iodothyronines.');
mc(2, 'hormones', 'Which hormone is an amino acid derivative?', 'Adrenaline', ['Glucagon', 'Progesterone', 'FSH'], 'Adrenaline and noradrenaline are derived from tyrosine. Glucagon and FSH are peptide or protein hormones.');
mc(2, 'hypothalamus', 'Hypothalamic hormones reach the anterior pituitary through', 'the portal circulation', ['the axons of neurons', 'the lymph', 'the cerebrospinal fluid only'], 'A portal system carries releasing and inhibiting hormones from the hypothalamus to the adenohypophysis.');
mc(2, 'hypothalamus', 'Somatostatin from the hypothalamus', 'inhibits the release of growth hormone from the pituitary', ['stimulates release of growth hormone', 'stimulates thyroxine release', 'inhibits oxytocin release in the uterus'], 'It is an inhibiting hormone. Releasing hormones such as GnRH stimulate the pituitary.');
mc(2, 'hypothalamus', 'Gonadotropin-releasing hormone (GnRH) stimulates the pituitary to secrete', 'LH and FSH', ['TSH and ACTH', 'GH and prolactin', 'oxytocin and vasopressin'], 'GnRH acts on the pars distalis to release the gonadotropins LH and FSH.');
mc(2, 'pituitary', 'The posterior pituitary stores and releases', 'oxytocin and vasopressin', ['GH and prolactin', 'TSH and ACTH', 'LH and FSH'], 'These two hormones are made by the hypothalamus and sent down axons to the neurohypophysis.');
mc(2, 'pituitary', 'Which of these is NOT secreted by the pars distalis?', 'Oxytocin', ['Prolactin', 'TSH', 'ACTH'], 'Oxytocin is a posterior pituitary hormone. The pars distalis makes GH, PRL, TSH, ACTH, LH and FSH.');
mc(2, 'pituitary', 'Prolactin regulates', 'growth of mammary glands and formation of milk in them', ['ejection of milk', 'ovulation', 'spermatogenesis'], 'Prolactin forms milk. Oxytocin is the one that ejects the milk.');
mc(2, 'pituitary', 'Thyroid stimulating hormone (TSH) stimulates the synthesis and secretion of', 'thyroid hormones from the thyroid gland', ['cortisol from the adrenal', 'insulin from the pancreas', 'oestrogen from the ovary'], 'TSH acts on the thyroid, ACTH on the adrenal cortex, and the gonadotropins on the gonads.');
mc(2, 'pituitary', 'ACTH stimulates the synthesis and secretion of', 'steroid hormones called glucocorticoids from the adrenal cortex', ['adrenaline from the adrenal medulla', 'glucagon from the pancreas', 'thyroxine from the thyroid'], 'ACTH acts on the adrenal cortex.');
mc(2, 'pituitary', 'In males, LH stimulates', 'synthesis and secretion of androgens from the Leydig cells', ['milk formation', 'ovulation', 'water reabsorption'], 'LH acts on the interstitial cells. FSH with androgens regulates spermatogenesis.');
mc(2, 'pituitary', 'Ovulation of a fully mature follicle is induced by', 'LH', ['FSH', 'oxytocin', 'TSH'], 'An LH surge in mid-cycle induces rupture of the Graafian follicle and release of the ovum. FSH stimulates follicle growth.');
mc(2, 'pituitary', 'Melanocyte stimulating hormone acts on', 'melanocytes and regulates skin pigmentation', ['hepatocytes', 'adipocytes', 'renal tubules'], 'MSH is secreted by the pars intermedia and acts on the pigment cells of the skin.');
mc(2, 'thyroid', 'The thyroid gland is made of', 'follicles and stromal tissues', ['islets and acini', 'cortex and medulla', 'lobules and Leydig cells'], 'The follicular cells make T<sub>3</sub> and T<sub>4</sub>. The gland lies on either side of the trachea, joined by an isthmus.');
mc(2, 'thyroid', 'Thyroid hormones play an important role in', 'regulating the basal metabolic rate', ['regulating blood glucose directly', 'milk ejection', 'water reabsorption in the kidney'], 'They support metabolism of carbohydrates, proteins and fats, red blood cell formation and water-electrolyte balance, and control the BMR.');
mc(2, 'thyroid', 'Thyrocalcitonin (TCT)', 'lowers blood calcium by reducing bone resorption', ['raises blood calcium', 'raises blood glucose', 'raises blood pressure'], 'TCT, from the thyroid, opposes the action of PTH.');
mc(2, 'parathyroid', 'How many parathyroid glands are present in humans?', 'Four', ['Two', 'Six', 'One'], 'There are four, on the back of the thyroid gland, one pair in each lobe.');
mc(2, 'parathyroid', 'PTH increases blood Ca<sup>2+</sup> by', 'stimulating bone resorption and increasing reabsorption of Ca<sup>2+</sup> in renal tubules', ['storing Ca<sup>2+</sup> in bones', 'increasing excretion of Ca<sup>2+</sup>', 'decreasing absorption of Ca<sup>2+</sup> from food'], 'PTH works on bone, kidney and the intestine to raise calcium.');
mc(2, 'thymus', 'The thymus plays a major role in', 'development of the immune system (T-lymphocytes)', ['digestion', 'hormonal control of blood sugar', 'secretion of bile'], 'Thymosins promote differentiation of T-lymphocytes, which provide cell-mediated immunity.');
mc(2, 'thymus', 'In old age the thymus', 'degenerates and secretes less thymosin, so immunity falls', ['becomes larger', 'secretes more thymosin', 'turns into a thyroid'], 'The thymus shrinks with age, so immune responses weaken.');
mc(2, 'adrenal', 'The zones of the adrenal cortex from outside to inside are', 'zona glomerulosa, zona fasciculata, zona reticularis', ['zona reticularis, zona fasciculata, zona glomerulosa', 'zona fasciculata, zona glomerulosa, zona reticularis', 'zona glomerulosa, zona reticularis, zona fasciculata'], 'The outer layer is the zona glomerulosa, then the zona fasciculata, with the zona reticularis innermost.');
mc(2, 'adrenal', 'Aldosterone acts mainly on', 'the renal tubules, increasing the reabsorption of Na<sup>+</sup> and water', ['the liver, breaking down glycogen', 'the bones', 'the thymus'], 'A mineralocorticoid. It also increases excretion of K<sup>+</sup> and phosphate ions.');
mc(2, 'adrenal', 'The function of cortisol is to', 'stimulate gluconeogenesis and have an anti-inflammatory effect', ['lower blood glucose', 'stimulate uterine contractions', 'make RBCs destroyed'], 'Cortisol raises glucose via gluconeogenesis, lipolysis and proteolysis, and suppresses the immune response.');
mc(2, 'adrenal', 'Which of these is an effect of adrenaline?', 'Increased heartbeat and rate of respiration', ['Decreased heartbeat', 'Constricted pupil', 'Lowered blood glucose'], 'Adrenaline increases alertness, pupil dilation, sweating, heart rate and breathing, and raises blood glucose.');
mc(2, 'pancreas', 'Glucagon', 'stimulates glycogenolysis and gluconeogenesis, raising blood glucose', ['stimulates glycogenesis', 'stimulates glucose uptake by cells', 'lowers blood glucose'], 'It acts mainly on liver cells. Insulin is the one for glycogenesis.');
mc(2, 'pancreas', 'Insulin acts mainly on', 'hepatocytes and adipocytes', ['neurons', 'osteocytes', 'RBCs'], 'It enhances glucose uptake and utilisation and glycogen formation in these cells.');
mc(2, 'gonads', 'Which is an effect of testosterone?', 'Growth of facial hair and a low-pitched voice', ['Development of mammary glands', 'Contraction of the uterus', 'Milk secretion'], 'Androgens support male secondary sexual characters and also stimulate spermatogenesis.');
mc(2, 'gonads', 'Oestrogen produces the following effect.', 'Growth of female secondary sex organs and secondary sex characters', ['Maintenance of the corpus luteum', 'Milk ejection', 'Growth of the prostate gland'], 'Oestrogen stimulates the growth of the female secondary sex organs, follicular development and mammary gland growth.');
mc(2, 'heart, kidney, GI tract', 'Atrial natriuretic factor (ANF) is secreted by the', 'atrial wall of the heart', ['ventricular wall of the heart', 'kidney', 'adrenal medulla'], 'When blood pressure rises, the atrial wall secretes ANF, which causes dilation of blood vessels and lowers blood pressure.');
mc(2, 'heart, kidney, GI tract', 'Secretin acts on the', 'exocrine pancreas to release water and bicarbonate', ['stomach to release HCl', 'gallbladder only', 'liver to make glycogen'], 'Secretin is made in the duodenum and stimulates the pancreas for water and bicarbonate ions.');
mc(2, 'heart, kidney, GI tract', 'Cholecystokinin (CCK) acts on', 'the pancreas and the gallbladder', ['the thyroid', 'the kidney', 'the heart'], 'CCK stimulates secretion of pancreatic enzymes and bile juice.');
mc(2, 'mechanism', 'Hormones whose receptors are on the cell membrane', 'do not enter the target cell but produce second messengers', ['enter the nucleus', 'are always steroids', 'bind directly to DNA'], 'Peptide, protein and catecholamine hormones bind to membrane receptors. They act through second messengers like cAMP, IP<sub>3</sub> and Ca<sup>2+</sup>.');
mc(2, 'mechanism', 'Hormones with intracellular receptors are mostly', 'steroid hormones and iodothyronines', ['peptide hormones', 'catecholamines', 'protein hormones'], 'They enter the cell and bind receptors in the cytoplasm or nucleus, then regulate gene expression.');
mc(2, 'mechanism', 'Which one is a second messenger?', 'cAMP', ['ATP only', 'insulin', 'Aldosterone'], 'cAMP, IP<sub>3</sub> and Ca<sup>2+</sup> are common second messengers.');
mc(2, 'disorders', 'Excess secretion of growth hormone in adults causes', 'acromegaly', ['gigantism', 'dwarfism', 'cretinism'], 'In adults after the growth plates close, GH makes the bones of the face, hands and feet enlarge. Excess in childhood gives gigantism.');
mc(2, 'disorders', 'Deficiency of GH in childhood results in', 'pituitary dwarfism', ['gigantism', 'acromegaly', 'goitre'], 'Low GH during growth leads to a short but normally proportioned body.');
mc(2, 'disorders', 'Diabetes insipidus is due to', 'deficiency of ADH (vasopressin)', ['deficiency of insulin', 'excess of cortisol', 'deficiency of thyroxine'], 'Without ADH the kidney cannot conserve water. The person passes large amounts of dilute urine.');
mc(2, 'disorders', 'Cretinism is caused by', 'hypothyroidism during infancy or pregnancy', ['hyperthyroidism', 'excess GH', 'lack of ADH'], 'It shows stunted growth, mental retardation, low IQ and abnormal skin.');
mc(2, 'disorders', 'Exophthalmic goitre (Graves’ disease) shows', 'enlarged thyroid, protruding eyeballs and high BMR', ['enlarged thyroid, low BMR and weight gain', 'small thyroid and slow heart rate', 'high blood glucose and ketone bodies'], 'It is a form of hyperthyroidism with raised thyroid hormones.');
mc(2, 'feedback', 'High thyroxine in blood switches off further TSH release. This is an example of', 'negative feedback', ['positive feedback', 'no feedback', 'neural reflex'], 'The product of the gland inhibits the hypothalamus and pituitary that stimulate it.');

// ---------------------------------------------------------------- Level 3
mc(3, 'disorders', 'A man has high blood glucose, passes much urine that contains glucose, and his urine also contains ketone bodies. The likely diagnosis is', 'diabetes mellitus', ['diabetes insipidus', 'Graves’ disease', 'Addison’s disease'], 'Prolonged hyperglycaemia, glucosuria and ketone bodies are features of lack of insulin action. In diabetes insipidus the urine is dilute and has no glucose.', 'Both are called diabetes because of much urine. Only mellitus has sugar in it.');
mc(3, 'disorders', 'A patient passes 10 litres of very dilute urine a day, and his urine and blood glucose tests are normal. Which hormone is deficient?', 'ADH (vasopressin)', ['Insulin', 'Aldosterone', 'Glucagon'], 'Without ADH the distal tubules reabsorb too little water. The glucose is normal, so insulin is not the cause.');
mc(3, 'disorders', 'A child with a normal body shape stops growing and is very short. Blood tests show low GH. This condition is', 'pituitary dwarfism', ['cretinism', 'gigantism', 'acromegaly'], 'Low GH gives a short but proportionate body. Cretinism also gives short height but with mental retardation and low thyroid hormone.', 'Cretinism = hypothyroid, with mental defects.');
mc(3, 'disorders', 'A 40-year-old person develops large hands, jaw and feet over some years. The cause is', 'excess GH after the growth plates have closed', ['excess GH before puberty', 'low thyroxine', 'excess cortisol'], 'This is acromegaly. In childhood excess GH would cause gigantism with a tall body.');
mc(3, 'disorders', 'Gigantism is caused by', 'too much growth hormone during childhood', ['too much thyroxine in adults', 'too little insulin', 'too much cortisol'], 'Excess GH when bones are still growing gives a very tall body.');
mc(3, 'disorders', 'A person has weight loss, fast heartbeat, high BMR, heat intolerance and bulging eyes. Which hormone level is likely high?', 'Thyroxine (T<sub>4</sub>) and T<sub>3</sub>', ['Insulin', 'PTH', 'ADH'], 'Hyperthyroidism raises the BMR. Exophthalmic goitre is its form with protruding eyes.');
mc(3, 'disorders', 'In iodine deficiency the thyroid gland enlarges because', 'low thyroxine removes the negative feedback, so more TSH is secreted and stimulates the gland', ['high thyroxine stimulates TSH', 'iodine stimulates cell growth directly', 'the pituitary stops making TSH'], 'Less T<sub>4</sub> means less feedback on the pituitary, so TSH rises and the thyroid tissue grows.', 'The enlarged gland is not making more hormone: it lacks iodine.');
mc(3, 'disorders', 'Muscle spasms (tetany) with low blood Ca<sup>2+</sup> point to', 'deficiency of parathyroid hormone', ['excess of parathyroid hormone', 'deficiency of insulin', 'excess of GH'], 'Without PTH, blood calcium falls, making nerves and muscles hyper-excitable.');
mc(3, 'disorders', 'A person has weakness, low blood glucose and low blood pressure, with dark skin patches and low Na<sup>+</sup> in blood. The likely cause is', 'Addison’s disease (adrenal cortex deficiency)', ['Cushing’s syndrome', 'Graves’ disease', 'Acromegaly'], 'Low cortisol and aldosterone lead to low glucose, low Na<sup>+</sup> and low BP. The pituitary releases more ACTH, which brings pigmentation.', 'Cushing’s is the opposite: excess cortisol.');
mc(3, 'disorders', 'Excess cortisol is expected to cause', 'high blood glucose, weight gain with a round face, and high blood pressure', ['low blood glucose', 'high calcium in bones', 'weight loss and low BP'], 'This is Cushing’s syndrome. Cortisol raises glucose through gluconeogenesis and causes fat redistribution.');
mc(3, 'pancreas', 'After a heavy meal, the blood glucose rises. The correct response is', 'increase in insulin and decrease in glucagon', ['increase in glucagon and decrease in insulin', 'increase in both', 'no change in either'], 'High glucose stimulates β-cells to release insulin, and glucagon release is reduced.');
mc(3, 'pancreas', 'During a long fast, the blood glucose is kept up mainly by', 'glucagon stimulating glycogenolysis and gluconeogenesis', ['insulin stimulating glycogenesis', 'ADH', 'PTH'], 'Glucagon is the hyperglycaemic hormone. Insulin is low in fasting.');
mc(3, 'pancreas', 'Which of these would a person with an insulin overdose likely show?', 'Low blood glucose with sweating and weakness', ['High blood glucose', 'Ketone bodies in urine and high glucose', 'High blood calcium'], 'Excess insulin makes the cells take up too much glucose, leading to hypoglycaemia.');
mc(3, 'pancreas', 'The islets of Langerhans make up about', '1 to 2 per cent of the pancreas', ['50 per cent of the pancreas', '20 per cent of the pancreas', 'the whole pancreas'], 'A normal pancreas has 1-2 million islets that are only 1-2% of its tissue. Most of it is exocrine.');
mc(3, 'adrenal', 'Which of these is controlled by ACTH?', 'Secretion of cortisol', ['Secretion of adrenaline', 'Secretion of insulin', 'Secretion of oxytocin'], 'The adrenal medulla is controlled by sympathetic nerves. ACTH controls the cortex.');
mc(3, 'adrenal', 'In a stress situation, which of these changes occurs through adrenaline?', 'Increased heart rate and increased glycogen breakdown', ['Decreased heart rate', 'Increased insulin release', 'Decreased respiration rate'], 'Adrenaline raises the heart rate, strength of contraction, respiration and blood glucose by glycogen breakdown.');
mc(3, 'adrenal', 'A person has low blood volume. Aldosterone secretion will', 'rise, so Na<sup>+</sup> and water are reabsorbed more', ['fall, so more water is lost', 'stay the same', 'rise, so more Na<sup>+</sup> is excreted'], 'Aldosterone helps to restore blood volume and pressure by Na<sup>+</sup> and water reabsorption.');
mc(3, 'adrenal', 'Which of these pairs is correct?', 'Zona glomerulosa : aldosterone', ['Zona reticularis : aldosterone', 'Adrenal medulla : cortisol', 'Zona fasciculata : adrenaline'], 'Mineralocorticoids come from the outer zona glomerulosa, glucocorticoids from the zona fasciculata, and adrenaline from the medulla.');
mc(3, 'pituitary', 'The hormone that causes milk ejection during suckling is', 'oxytocin', ['prolactin', 'progesterone', 'vasopressin'], 'Prolactin makes milk, but suckling releases oxytocin, which contracts the cells around the alveoli to eject it.', 'Milk production vs milk ejection.');
mc(3, 'pituitary', 'Which of these is correctly paired?', 'FSH : growth of ovarian follicles', ['LH : growth of ovarian follicles', 'ACTH : ejection of milk', 'GH : water reabsorption'], 'FSH stimulates follicles and oestrogen secretion in females. LH causes ovulation.');
mc(3, 'pituitary', 'Which of these hormones are tropic hormones of the pituitary?', 'TSH, ACTH, LH and FSH', ['Insulin and glucagon', 'Oxytocin and vasopressin', 'GH and thyroxine'], 'Tropic hormones control the activity of another endocrine gland.');
mc(3, 'pituitary', 'The neurohypophysis does NOT', 'synthesise any hormone itself', ['store oxytocin', 'release vasopressin', 'receive axons from the hypothalamus'], 'Hormones released by the pars nervosa are made in the hypothalamus. The pars nervosa only stores and releases them.');
mc(3, 'pituitary', 'The adenohypophysis is made of', 'pars distalis and pars intermedia', ['pars nervosa only', 'pars distalis and pars nervosa', 'pars intermedia and pars nervosa'], 'The pituitary has an adenohypophysis (pars distalis and pars intermedia) and a neurohypophysis (pars nervosa).');
mc(3, 'pineal', 'Melatonin influences', 'the sleep-wake cycle and the 24-hour body rhythm', ['blood glucose', 'urine volume', 'milk secretion'], 'It also affects body temperature, metabolism, pigmentation, the menstrual cycle and defence capability.');
mc(3, 'thyroid', 'The thyroid hormone formed with four iodine atoms is', 'tetraiodothyronine (T<sub>4</sub>, thyroxine)', ['triiodothyronine (T<sub>3</sub>)', 'thyrocalcitonin', 'thymosin'], 'T<sub>4</sub> has four iodine atoms and T<sub>3</sub> has three.');
mc(3, 'thyroid', 'Hypothyroidism in a pregnant woman can cause', 'stunted growth and mental retardation of the baby', ['gigantism in the baby', 'acromegaly', 'diabetes insipidus'], 'This is cretinism. In adult women hypothyroidism can cause irregular menstrual cycles.');
mc(3, 'parathyroid', 'Parathyroid hormone and thyrocalcitonin are', 'antagonistic hormones for blood Ca<sup>2+</sup>', ['synergistic hormones for blood Ca<sup>2+</sup>', 'both made by the thyroid', 'both made by the parathyroid'], 'PTH raises and TCT lowers blood Ca<sup>2+</sup>. They keep it within a narrow range.');
mc(3, 'heart, kidney, GI tract', 'Erythropoietin acts on', 'the bone marrow, to stimulate formation of RBCs', ['the liver, to make glycogen', 'the stomach, to produce acid', 'the kidney tubules, to reabsorb water'], 'It is released by the kidney when oxygen is low. The target is bone marrow.', 'The source is the kidney, but the target is not.');
mc(3, 'heart, kidney, GI tract', 'Which hormone is secreted by the stomach and acts on gastric glands?', 'Gastrin', ['Secretin', 'CCK', 'Insulin'], 'Gastrin stimulates HCl and pepsinogen secretion. Secretin and CCK come from the small intestine.');
mc(3, 'heart, kidney, GI tract', 'GIP', 'inhibits gastric secretion and motility', ['stimulates gastric acid', 'stimulates bile release', 'raises BP'], 'GIP is the gastric inhibitory peptide.');
mc(3, 'heart, kidney, GI tract', 'A fall in blood pressure triggers renin release. A rise in blood pressure causes the atrial wall to release', 'ANF', ['erythropoietin', 'gastrin', 'aldosterone'], 'ANF dilates vessels and opposes the renin-angiotensin mechanism.');
mc(3, 'mechanism', 'Adrenaline acts on its target cell by', 'binding to a membrane receptor and raising cAMP', ['entering the nucleus', 'binding to a DNA sequence', 'being converted to cortisol'], 'It is an amino acid derivative and cannot cross the membrane. The receptor produces a second messenger.');
mc(3, 'mechanism', 'Steroid hormones act by', 'binding to intracellular receptors and regulating gene expression', ['binding to membrane receptors and making cAMP', 'being broken down at the membrane', 'opening gap junctions'], 'Being lipid-soluble, they enter the cell and the hormone-receptor complex acts on the genome.');
mc(3, 'mechanism', 'The effect of a steroid hormone on a cell takes longer to appear than that of adrenaline because', 'it involves changes in gene expression and protein synthesis', ['it is not carried in blood', 'it has no receptor', 'it is a protein'], 'Membrane receptor and second messengers act in seconds. Gene-level changes take longer and last longer.');
mc(3, 'feedback', 'Which is an example of positive feedback?', 'Oxytocin release during childbirth, which increases uterine contractions that raise more oxytocin', ['Insulin lowering blood glucose and so reducing its own release', 'Thyroxine reducing TSH', 'Cortisol inhibiting ACTH'], 'Uterine stretching raises oxytocin, contraction raises stretching further. The other three are negative feedback.');
mc(3, 'feedback', 'Which of these is a negative feedback?', 'High cortisol inhibits CRH and ACTH', ['High oxytocin increases its own release', 'High LH just before ovulation raises more LH', 'Milk suckling increases more prolactin'], 'Cortisol turns off its own control signals. The others are positive or stimulatory loops.');
asr(3, 'pancreas', 'Insulin is a hypoglycaemic hormone.', 'It stimulates the uptake of glucose by cells and the formation of glycogen.', 0, 'This lowers blood glucose, so R explains A.');
asr(3, 'pancreas', 'Glucagon is a hyperglycaemic hormone.', 'It stimulates glycogenolysis and gluconeogenesis.', 0, 'Breaking down glycogen and making glucose from non-carbohydrates raises blood glucose.');
asr(3, 'thyroid', 'Deficiency of iodine causes goitre.', 'Iodine is required for the synthesis of thyroid hormones.', 0, 'Without iodine, T<sub>4</sub> falls, TSH rises and the gland enlarges.');
asr(3, 'pituitary', 'Oxytocin is a posterior pituitary hormone made in the pituitary gland.', 'The neurohypophysis stores hormones made by the hypothalamus.', 3, 'A is false: oxytocin is made in the hypothalamus. R is true.');
asr(3, 'disorders', 'Diabetes insipidus and diabetes mellitus both cause large urine volume.', 'Both are caused by deficiency of insulin.', 2, 'A is true. R is false: DI is due to ADH deficiency, DM to insulin.');
asr(3, 'adrenal', 'Adrenaline is called the "fight or flight" hormone.', 'It increases heart rate and breakdown of glycogen, providing energy in emergencies.', 0, 'The changes prepare the body for action.');
asr(3, 'parathyroid', 'PTH is hypercalcaemic.', 'It reduces the reabsorption of Ca<sup>2+</sup> by the renal tubules.', 2, 'A is true: it raises blood Ca<sup>2+</sup>. R is false: it increases Ca<sup>2+</sup> reabsorption.');
asr(3, 'thymus', 'The immune response of old people is weaker.', 'The thymus degenerates in old age and secretes less thymosin.', 0, 'Thymosins help T-lymphocyte differentiation, so reduced secretion weakens immunity.');
asr(3, 'mechanism', 'Steroid hormones can cross the plasma membrane of a target cell.', 'Steroid hormones are lipid-soluble.', 0, 'Being lipid-soluble, they diffuse through the membrane.');
asr(3, 'hormones', 'Endocrine glands release hormones through ducts.', 'Hormones are carried in blood to the target organs.', 3, 'A is false: endocrine glands are ductless. R is true.');
stm(3, 'pituitary', 'The pars intermedia secretes MSH.', 'Oxytocin and ADH are secreted by the anterior pituitary.', 2, 'I is right. II is wrong: they are released from the posterior pituitary (made in the hypothalamus).');
stm(3, 'adrenal', 'The adrenal cortex secretes cortisol and aldosterone.', 'The adrenal medulla secretes adrenaline and noradrenaline.', 0, 'Both are correct.');
stm(3, 'pancreas', 'The α-cells of the islets secrete glucagon.', 'The β-cells of the islets secrete somatostatin.', 2, 'I is correct. β-cells secrete insulin; somatostatin comes from the δ-cells.');
stm(3, 'thyroid', 'Thyroid hormones control the basal metabolic rate.', 'Thyroxine secretion is stimulated by ACTH.', 2, 'I is true. II is false: TSH stimulates the thyroid.');
stm(3, 'gonads', 'Testosterone is secreted by the Leydig cells.', 'Progesterone is secreted mainly by the testis.', 2, 'I is true. II is false: progesterone is secreted by the ovary (corpus luteum).');
stm(3, 'heart, kidney, GI tract', 'The heart secretes ANF.', 'The kidney secretes erythropoietin.', 0, 'Both are correct statements.');
stm(3, 'mechanism', 'Peptide hormones act through membrane receptors.', 'Thyroid hormones act through membrane receptors only.', 2, 'I is correct. II is wrong: thyroid hormones (iodothyronines) act on intracellular receptors.');
stm(3, 'hormones', 'Hormones are secreted in large quantities.', 'Hormones may act on distant target cells through blood.', 3, 'I is wrong: they are made in trace amounts. II is right.');
cnt(3, 'pituitary', 'How many of these are secreted by the posterior pituitary: oxytocin, FSH, vasopressin, prolactin, MSH?', 'Two', ['One', 'Three', 'Four'], 'Only oxytocin and vasopressin. FSH and prolactin come from the pars distalis and MSH from the pars intermedia.');
cnt(3, 'hormones', 'How many of these are steroid hormones: cortisol, insulin, aldosterone, testosterone, glucagon?', 'Three', ['Two', 'Four', 'Five'], 'Cortisol, aldosterone and testosterone are steroids; insulin and glucagon are peptides.');
match(3, 'hormones', 'cm1', 'Glands and hormones',
  ['A. Pineal', 'B. Thymus', 'C. Parathyroid', 'D. Adrenal medulla'],
  ['p. Thymosin', 'q. Melatonin', 'r. PTH', 's. Adrenaline'],
  'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'],
  'Pineal makes melatonin, thymus makes thymosin, parathyroid makes PTH and the adrenal medulla makes adrenaline.');
match(3, 'hormones', 'cm2', 'Hormones and actions',
  ['A. Glucagon', 'B. Aldosterone', 'C. Oxytocin', 'D. ADH'],
  ['p. Reabsorption of Na<sup>+</sup> in renal tubules', 'q. Milk ejection', 'r. Glycogenolysis', 's. Reabsorption of water in distal tubules'],
  'A-r, B-p, C-q, D-s', ['A-p, B-r, C-q, D-s', 'A-r, B-p, C-s, D-q', 'A-q, B-p, C-r, D-s'],
  'Glucagon breaks down glycogen, aldosterone retains Na<sup>+</sup>, oxytocin ejects milk, ADH retains water.');
match(3, 'disorders', 'cm3', 'Disorders and causes',
  ['A. Acromegaly', 'B. Diabetes insipidus', 'C. Addison’s disease', 'D. Cretinism'],
  ['p. Hypothyroidism in infancy', 'q. Deficiency of ADH', 'r. Excess GH in adults', 's. Deficiency of adrenal cortex hormones'],
  'A-r, B-q, C-s, D-p', ['A-q, B-r, C-s, D-p', 'A-r, B-q, C-p, D-s', 'A-s, B-q, C-r, D-p'],
  'Acromegaly is excess GH in adults, DI lack of ADH, Addison’s lack of adrenocortical hormones and cretinism early hypothyroidism.');
match(3, 'heart, kidney, GI tract', 'cm4', 'Gut hormones and actions',
  ['A. Gastrin', 'B. Secretin', 'C. CCK', 'D. GIP'],
  ['p. Water and bicarbonate from pancreas', 'q. HCl and pepsinogen', 'r. Pancreatic enzymes and bile', 's. Inhibits gastric secretion'],
  'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-r, C-p, D-s', 'A-s, B-p, C-r, D-q'],
  'Gastrin acts on gastric glands, secretin on the pancreas for water and bicarbonate, CCK on pancreas and gallbladder, GIP inhibits stomach.');
items.push({ id: nid(), type: 'nat', level: 3, format: 'integer', exams: E, sub: 'pituitary', q: 'How many hormones are secreted by the pars distalis of the human pituitary? (Do not count MSH of the pars intermedia.)', answer: 6, tol: 0, calc: () => ['GH', 'PRL', 'TSH', 'ACTH', 'LH', 'FSH'].length, sol: 'The pars distalis makes GH, prolactin, TSH, ACTH, LH and FSH, a total of 6. MSH comes from the pars intermedia.', trap: 'MSH belongs to the pars intermedia.' });
items.push({ id: nid(), type: 'nat', level: 3, format: 'integer', exams: E, sub: 'parathyroid', q: 'How many parathyroid glands are there in the human body?', answer: 4, tol: 0, calc: () => 2 * 2, sol: 'One pair in each of the two thyroid lobes: 2 x 2 = 4.' });
items.push({ id: nid(), type: 'nat', level: 3, format: 'integer', exams: E, sub: 'adrenal', q: 'How many zones does the adrenal cortex have?', answer: 3, tol: 0, calc: () => ['glomerulosa', 'fasciculata', 'reticularis'].length, sol: 'Zona glomerulosa, zona fasciculata and zona reticularis: three.' });

// ---------------------------------------------------------------- Level 4
mc(4, 'feedback', 'A patient has high TSH and low T<sub>4</sub> in blood. The fault is most likely in the', 'thyroid gland itself (primary hypothyroidism)', ['pituitary (it makes too little TSH)', 'hypothalamus (too little TRH)', 'adrenal cortex'], 'The pituitary is working (TSH is high) but the thyroid is not responding, so T<sub>4</sub> is low and feedback is lost. If the pituitary or hypothalamus were at fault, TSH would be low.', 'High TSH means the pituitary is fine.');
mc(4, 'feedback', 'A patient has low T<sub>4</sub> and low TSH. The fault is most likely in the', 'pituitary or hypothalamus', ['thyroid only', 'parathyroid', 'pancreas'], 'The thyroid is not stimulated because TSH is low. The cause is higher up in the axis, so the thyroid would respond to TSH given from outside.');
mc(4, 'feedback', 'A tumour in the adrenal cortex makes cortisol in excess. What happens to ACTH in the blood?', 'It falls because of negative feedback', ['It rises', 'It stays unchanged', 'It becomes the same as cortisol'], 'High cortisol inhibits CRH and ACTH release. The other adrenal zones, which depend on ACTH, may shrink.', 'The tumour acts independently of ACTH.');
mc(4, 'feedback', 'A person takes steroid tablets (like cortisol) for months and then stops them suddenly. The risk is', 'adrenal insufficiency, because the adrenal cortex was suppressed by feedback', ['adrenal medulla hypertrophy', 'diabetes insipidus', 'goitre'], 'External cortisol lowers ACTH, the adrenal cortex becomes small and cannot rapidly make cortisol when the tablets stop.');
mc(4, 'pituitary', 'If the pituitary stalk is cut, which hormones will still be found in blood, at least initially?', 'Oxytocin and ADH from the cut axon ends, in lower amounts', ['None of the pituitary hormones', 'Only GH', 'Only TSH'], 'The posterior hormones are made in the hypothalamus and stored in nerve endings. Some release continues from the stump. The anterior pituitary loses its releasing hormones via the portal vessels.');
mc(4, 'pituitary', 'Removal of the posterior pituitary would NOT directly affect', 'secretion of growth hormone', ['water reabsorption in kidney', 'milk ejection', 'uterine contractions in labour'], 'GH comes from the anterior pituitary. ADH and oxytocin are stored and released from the posterior part.');
mc(4, 'pituitary', 'Which hormone from the pituitary has a role in both the female and male reproductive systems?', 'LH', ['Oxytocin only', 'Prolactin', 'MSH'], 'LH acts on Leydig cells in the male and on the follicle and corpus luteum in the female.');
mc(4, 'pituitary', 'A woman who delivers a baby cannot produce milk. Blood tests show low prolactin. The part of the gland affected is', 'the pars distalis', ['the pars nervosa', 'the pineal', 'the thymus'], 'Prolactin is an anterior pituitary hormone, so the problem is in the adenohypophysis.');
mc(4, 'pituitary', 'A woman has milk production but cannot eject milk when the baby suckles. The failure is in the release of', 'oxytocin', ['prolactin', 'GH', 'progesterone'], 'Prolactin makes the milk. Suckling stimulates oxytocin, which ejects it.');
mc(4, 'adrenal', 'The two adrenal parts have different origins. Which of these is correct?', 'The medulla is neural in origin and secretes catecholamines', ['The cortex is neural in origin', 'The medulla secretes steroids', 'The cortex secretes adrenaline'], 'The adrenal medulla arises from neural crest tissue, like a modified sympathetic ganglion. The cortex makes steroids.');
mc(4, 'adrenal', 'Which of these is correctly paired? Gland : hormone : effect', 'Adrenal cortex : aldosterone : Na<sup>+</sup> reabsorption', ['Adrenal medulla : cortisol : gluconeogenesis', 'Adrenal cortex : adrenaline : pupil dilation', 'Adrenal medulla : aldosterone : K<sup>+</sup> reabsorption'], 'Only adrenal cortex : aldosterone : Na<sup>+</sup> reabsorption has a correct gland, hormone and effect. Cortisol and aldosterone come from the cortex, not the medulla, and adrenaline comes from the medulla.');
mc(4, 'adrenal', 'Cortisol has all of these effects EXCEPT', 'stimulation of the immune response', ['gluconeogenesis', 'lipolysis', 'proteolysis'], 'Cortisol suppresses the immune response and is anti-inflammatory. The others are true.', 'Read EXCEPT.');
mc(4, 'adrenal', 'Hyperpigmentation seen in Addison’s disease is linked to', 'high ACTH and related peptides stimulating melanocytes', ['high aldosterone', 'low thyroxine', 'low insulin'], 'Low cortisol removes feedback, ACTH rises, and ACTH (and MSH-like peptides from the same precursor) darken the skin.');
mc(4, 'pancreas', 'A person has a normal insulin level but cells do not respond to it. The result will be', 'high blood glucose, as in type 2 diabetes', ['low blood glucose', 'high blood calcium', 'low blood pressure'], 'This is insulin resistance. The glucose cannot enter cells and the blood level stays high.');
mc(4, 'pancreas', 'In a person with untreated type 1 diabetes, ketone bodies appear in blood because', 'cells cannot use glucose and break down fats for energy', ['too much glucose is oxidised', 'too much insulin is present', 'the kidney secretes ketones'], 'Without insulin, glucose cannot be used, and fats are broken down in large amounts, forming ketone bodies.');
mc(4, 'pancreas', 'A person with a pancreatic tumour of β-cells making excess insulin will show', 'low blood glucose episodes', ['high blood glucose', 'increased glucagon', 'glucose in urine'], 'Insulin lowers blood glucose. An insulinoma causes hypoglycaemia.');
mc(4, 'pancreas', 'Which of these has both an endocrine and an exocrine function?', 'Pancreas', ['Thyroid', 'Adrenal', 'Pituitary'], 'The pancreas makes digestive juice (exocrine) and insulin and glucagon (endocrine). The ovary and testis also make gametes, as a different form of dual function.');
mc(4, 'gonads', 'Which of these hormones is required to maintain the endometrium and pregnancy?', 'Progesterone', ['FSH', 'Testosterone', 'ADH'], 'Progesterone keeps the endometrium ready for implantation and pregnancy.');
mc(4, 'gonads', 'The hormone responsible for spermatogenesis along with FSH is', 'testosterone (androgens)', ['oestrogen', 'oxytocin', 'prolactin'], 'FSH and androgens together regulate spermatogenesis.');
mc(4, 'heart, kidney, GI tract', 'A patient with chronic kidney failure often has anaemia. The hormonal reason is', 'less erythropoietin from the damaged kidney', ['more ADH', 'less insulin', 'less gastrin'], 'Erythropoietin from the juxtaglomerular cells of the kidney stimulates RBC formation in marrow. Damaged kidneys make less of it.', 'The kidney is an endocrine organ too.');
mc(4, 'heart, kidney, GI tract', 'A person who has lost a lot of blood. Which of these hormonal changes is expected?', 'More aldosterone and ADH, less ANF', ['Less aldosterone and ADH', 'More ANF', 'More ANF and less ADH'], 'Low blood volume leads to renin, angiotensin II, aldosterone and ADH to conserve Na<sup>+</sup> and water. ANF (released on high BP) is reduced.');
mc(4, 'heart, kidney, GI tract', 'Which pair of hormones is made in the small intestine and acts on the pancreas?', 'Secretin and CCK', ['Gastrin and GIP', 'Insulin and glucagon', 'ANF and secretin'], 'Secretin (water, bicarbonate) and CCK (enzymes) act on the exocrine pancreas. Gastrin is from the stomach.');
mc(4, 'mechanism', 'A hormone, after binding to a membrane receptor, increases intracellular cAMP. cAMP acts as', 'a second messenger that triggers cellular responses', ['a first messenger', 'a hormone receptor', 'an enzyme'], 'The hormone is the first messenger. cAMP relays the message inside.');
mc(4, 'mechanism', 'Which of these is an incorrect pair?', 'Cortisol : membrane receptor with cAMP', ['Thyroxine : intracellular receptor', 'Glucagon : membrane receptor', 'Oestrogen : intracellular receptor'], 'Cortisol is a steroid with an intracellular receptor. The other pairs are right.');
mc(4, 'mechanism', 'The hormone-receptor complex of steroid hormones interacts with', 'the genome to regulate gene expression', ['the cell membrane only', 'mitochondria only', 'cAMP only'], 'This leads to cumulative physiological and developmental effects.');
stm(4, 'mechanism', 'All hormones act through second messengers.', 'Hormones with intracellular receptors regulate gene expression.', 3, 'I is false: steroid and thyroid hormones act through intracellular receptors. II is correct.');
stm(4, 'pituitary', 'Hypothalamic hormones reach the posterior pituitary via axons.', 'Hypothalamic hormones reach the anterior pituitary via the portal circulation.', 0, 'Both are correct. Posterior hormones go along axons; releasing and inhibiting hormones go through portal vessels.');
stm(4, 'parathyroid', 'PTH acts on bone to cause resorption.', 'PTH reduces the reabsorption of Ca<sup>2+</sup> in the kidney tubule.', 2, 'I is right. II is wrong: PTH increases tubular reabsorption of Ca<sup>2+</sup>.');
stm(4, 'adrenal', 'Adrenaline and noradrenaline are catecholamines.', 'They are secreted from the adrenal cortex.', 2, 'I is right. II is wrong: they come from the medulla.');
stm(4, 'thyroid', 'Graves’ disease is a form of hyperthyroidism.', 'Simple goitre is a form of hyperthyroidism.', 2, 'I is right. II is wrong: simple goitre is due to iodine deficiency, so there is hypothyroidism.', 'Both diseases show an enlarged gland, but one is high and the other is low hormone.');
asr(4, 'feedback', 'Thyroid enlargement in iodine deficiency is accompanied by a high TSH level.', 'Low T<sub>4</sub> removes the negative feedback on the pituitary.', 0, 'With little T<sub>4</sub>, TSH rises, and TSH is the growth stimulus for the gland.');
asr(4, 'disorders', 'A person with Graves’ disease usually has a low TSH level.', 'High thyroid hormone levels give negative feedback on the pituitary.', 0, 'High T<sub>3</sub>/T<sub>4</sub> suppress TSH. In Graves’ disease the thyroid is driven by antibodies, not by TSH.');
asr(4, 'adrenal', 'Cortisol is called a stress hormone.', 'Cortisol raises blood glucose, helping the body to meet its energy needs.', 0, 'Gluconeogenesis, lipolysis and proteolysis supply energy during stress.');
asr(4, 'hormones', 'Peptide hormones need receptors on the cell surface.', 'Peptide hormones are lipid-soluble and diffuse through the membrane.', 2, 'A is true. R is false: they are water-soluble and cannot cross the membrane.');
asr(4, 'pituitary', 'ADH lowers urine volume.', 'ADH causes reabsorption of water by the distal tubules of the nephron.', 0, 'More water goes back into blood, so a smaller volume of concentrated urine forms.');
pass('cp1', 'Passage: three blood reports', 'Report X: blood glucose 280 mg/dL (high), urine glucose present, insulin very low. Report Y: blood glucose normal, urine very dilute and about 8 litres per day, urine glucose absent, ADH low. Report Z: blood Ca<sup>2+</sup> low, muscles in spasm, PTH low, thyroid hormones normal.');
pq('cp1', 4, 'disorders', 'Report X is most likely of a patient with', 'diabetes mellitus', ['diabetes insipidus', 'hypoparathyroidism', 'Addison’s disease'], 'High glucose, glucosuria and low insulin indicate diabetes mellitus.');
pq('cp1', 4, 'disorders', 'Report Y is most likely of a patient with', 'diabetes insipidus', ['diabetes mellitus', 'goitre', 'acromegaly'], 'Low ADH means little water reabsorption: large amounts of dilute urine with normal glucose.');
pq('cp1', 4, 'disorders', 'Report Z is most likely of a patient with', 'hypoparathyroidism', ['hyperparathyroidism', 'hyperthyroidism', 'diabetes mellitus'], 'Low PTH lowers blood calcium and causes tetany.');
pass('cp2', 'Passage: an experiment on a rat', 'A rat’s thyroid gland is removed. After some days the rat is sluggish, with a low metabolic rate, and the level of TSH in blood is high. The rat is then given daily thyroxine injections. The TSH level falls to normal and the rat becomes active again. A second rat has its pituitary removed; its thyroid shrinks, and thyroxine in blood is low.');
pq('cp2', 4, 'feedback', 'Why was TSH high in the first rat after thyroidectomy?', 'Thyroxine was absent, so negative feedback on the pituitary was lost', ['TSH is made by the thyroid', 'The pituitary was damaged', 'Thyroxine stimulates TSH'], 'No thyroxine means no feedback. The pituitary keeps on secreting TSH.');
pq('cp2', 4, 'feedback', 'The fall of TSH after thyroxine injections shows', 'negative feedback by thyroxine on the pituitary/hypothalamus', ['positive feedback by thyroxine', 'direct action of TSH on the thyroid', 'that TSH is a steroid'], 'When thyroxine is restored, it inhibits TSH release.');
pq('cp2', 4, 'pituitary', 'The shrunken thyroid of the second rat shows that', 'TSH is needed to maintain the size and activity of the thyroid', ['thyroxine is needed to make TSH', 'the pituitary makes thyroxine', 'iodine is not needed'], 'Without TSH, the thyroid is not stimulated and shrinks.');

// ---------------------------------------------------------------- Level 5
mc(5, 'hypothalamus', 'Which of these correctly describes the hypothalamus?', 'It has neurosecretory cells that make releasing and inhibiting hormones for the pituitary', ['It is a part of the pituitary', 'It makes thyroxine', 'It is in the hindbrain'], 'The hypothalamus is part of the forebrain. Its hormones control the pituitary. It does not make thyroxine.');
mc(5, 'hypothalamus', 'Which hypothalamic hormone has an inhibitory effect on the pituitary?', 'Somatostatin', ['GnRH', 'Oxytocin', 'Insulin'], 'Somatostatin inhibits release of growth hormone. GnRH is a releasing hormone.');
mc(5, 'mechanism', 'Which of these steps is in the correct sequence for a peptide hormone?', 'Hormone binds a membrane receptor, a second messenger forms, a cellular response occurs', ['Hormone enters the nucleus, binds DNA, a second messenger forms', 'Second messenger forms, hormone binds, cell responds', 'Hormone is broken down, a receptor forms, cAMP binds DNA'], 'The first messenger is the hormone. The receptor produces second messengers (cAMP, IP<sub>3</sub>, Ca<sup>2+</sup>) that regulate metabolism.');
mc(5, 'mechanism', 'A drug that blocks the formation of cAMP will most likely reduce the response to', 'adrenaline', ['cortisol', 'thyroxine', 'oestrogen'], 'Adrenaline acts through a membrane receptor and cAMP. The other three act through intracellular receptors.', 'Steroids and thyroid hormones do not use cAMP.');
mc(5, 'mechanism', 'Which of these hormone pairs act on the same kind of receptor?', 'Cortisol and oestrogen', ['Cortisol and insulin', 'Adrenaline and thyroxine', 'Glucagon and testosterone'], 'Cortisol and oestrogen are both steroids with intracellular receptors. The other pairs combine membrane and intracellular types.');
mc(5, 'disorders', 'Which of the following correctly differentiates gigantism from acromegaly?', 'Gigantism: excess GH before the growth plates close; acromegaly: excess GH after', ['Gigantism: lack of GH; acromegaly: excess GH', 'Gigantism: excess GH after the growth plates close; acromegaly: before', 'Gigantism: excess thyroxine; acromegaly: excess insulin'], 'Both are excess GH. The timing decides the outcome: long bone growth in children, thickening of bones of the face and extremities in adults.');
mc(5, 'disorders', 'The conditions DI, goitre, acromegaly and cretinism involve hormones from', 'the pituitary, thyroid, pituitary and thyroid in that order', ['the pancreas, thyroid, pituitary and adrenal in that order', 'the thyroid, thyroid, pituitary and pituitary in that order', 'the pineal, thymus, thyroid and adrenal in that order'], 'DI: ADH (pituitary); goitre: thyroid hormones; acromegaly: GH (pituitary); cretinism: thyroid hormones.');
mc(5, 'disorders', 'Which of these is correct about Addison’s disease and Cushing’s syndrome?', 'Addison’s: low cortisol, hypotension and hypoglycaemia; Cushing’s: high cortisol, hypertension and hyperglycaemia', ['Both are due to low cortisol', 'Addison’s: high glucose; Cushing’s: low glucose', 'Both show high ACTH'], 'Addison’s is a deficiency of adrenocortical hormones and Cushing’s an excess of cortisol.');
mc(5, 'disorders', 'Graves’ disease differs from simple goitre because in Graves’ disease', 'thyroid hormone levels are high and the BMR is raised', ['iodine is lacking', 'TSH is high', 'the BMR is low'], 'Graves’ disease is hyperthyroidism, often driven by an antibody that stimulates the thyroid, so TSH is low. In simple goitre T<sub>4</sub> is low and TSH high.');
mc(5, 'thyroid', 'A student claims that the thyroid gland is made of two lobes joined by an isthmus and lies near the', 'trachea', ['stomach', 'kidney', 'spinal cord'], 'The two lobes are on either side of the trachea (windpipe) and connected by a thin isthmus.');
mc(5, 'parathyroid', 'Calcium balance is held by the combined action of', 'PTH and TCT (with vitamin D)', ['insulin and glucagon', 'ADH and aldosterone', 'GH and prolactin'], 'PTH raises calcium and TCT lowers it. The NCERT text says they play a significant role in calcium balance.');
mc(5, 'thymus', 'Which statement about thymosins is correct?', 'They promote T-lymphocyte differentiation and also promote antibody production', ['They are made by the thymus and are steroids', 'They raise blood calcium', 'They are produced in greater amounts in old age'], 'They support cell-mediated immunity and humoral immunity. Their level falls with age as the thymus degenerates.');
mc(5, 'pineal', 'A traveller crosses time zones and has trouble sleeping. The hormone mainly involved in resetting the cycle is', 'melatonin', ['cortisol', 'insulin', 'glucagon'], 'Melatonin from the pineal gland regulates the diurnal rhythm and sleep-wake cycle.');
mc(5, 'gonads', 'Which of these is NOT an effect of testosterone?', 'Growth of mammary glands', ['Development of the prostate and seminal vesicles', 'Increased muscle growth', 'Stimulation of spermatogenesis'], 'Testosterone does the male-specific tasks. Mammary growth is by oestrogen and progesterone.');
mc(5, 'gonads', 'The hormone from the ovary that stimulates formation of alveoli in the mammary glands is', 'progesterone', ['oestrogen', 'FSH', 'oxytocin'], 'Progesterone acts on mammary glands to form alveoli and milk-secreting cells. Oestrogen causes growth of the ducts.', 'Oestrogen is linked to growth of ducts; alveoli depend on progesterone.');
mc(5, 'heart, kidney, GI tract', 'Select the correct set of hormones secreted from non-endocrine organs.', 'ANF (heart), erythropoietin (kidney), gastrin and secretin (gut)', ['Insulin (heart), ANF (kidney), gastrin (gut)', 'ANF (kidney), erythropoietin (heart), secretin (gut)', 'Thymosin (heart), ANF (kidney), CCK (pancreas)'], 'Heart: ANF; kidney: erythropoietin; GI tract: gastrin, secretin, CCK, GIP.');
cnt(5, 'mixed', 'How many of these are correct? (1) Oxytocin is made in the posterior pituitary. (2) Thymosin is a hormone of the thymus. (3) Insulin is made by α-cells. (4) PTH increases blood calcium. (5) Aldosterone increases Na<sup>+</sup> reabsorption.', 'Three', ['Two', 'Four', 'Five'], '(1) false: it is made in the hypothalamus. (2) true. (3) false: β-cells. (4) true. (5) true. So three are correct.');
cnt(5, 'mixed', 'How many of the following hormones act through intracellular receptors: cortisol, adrenaline, thyroxine, glucagon, oestrogen, insulin, aldosterone?', 'Four', ['Three', 'Five', 'Two'], 'Cortisol, thyroxine, oestrogen and aldosterone act through intracellular receptors. Adrenaline, glucagon and insulin use membrane receptors.');
asr(5, 'mixed', 'Both the pancreas and the gonads are said to be dual-function organs.', 'The pancreas has endocrine and exocrine parts, while the gonads produce both gametes and hormones.', 0, 'The pancreas makes digestive juice and insulin and glucagon. The gonads make gametes and sex hormones.');
asr(5, 'pituitary', 'In humans, the pars intermedia is almost merged with the pars distalis.', 'MSH is the only hormone released by the pars intermedia.', 1, 'Both are as NCERT states. But the merging is a fact of anatomy and R does not explain it, so R is a separate true statement.', 'Do not choose the explanation option just because both are true.');
